          texto:
            "En el libro quinto, Smith enumera lo que un Estado tiene que hacer y pagar. Lo primero, la defensa. Lo segundo, la justicia, con jueces independientes. Lo tercero, las obras públicas: caminos, puentes, canales y puertos, que ningún particular construiría porque no le saldrían a cuenta.",
