            "Tetlock y su mujer, la psicóloga Barbara Mellers, montaron uno de los cinco equipos, el Good Judgment Project, y lo llenaron de voluntarios reclutados por internet: profesores jubilados, ingenieros, un ama de casa, un fabricante de tuberías, gente sin ninguna credencial en política internacional.",
